// Cache-aside in C#
using StackExchange.Redis;
using System.Text.Json;

public class UserService
{
    private readonly IDatabase _redis;
    private readonly AppDbContext _db;

    public UserService(IConnectionMultiplexer redis, AppDbContext db)
    {
        _redis = redis.GetDatabase();
        _db = db;
    }

    public async Task<User?> GetUserAsync(int id)
    {
        var cached = await _redis.StringGetAsync($"user:{id}");
        if (cached.HasValue)
        {
            return JsonSerializer.Deserialize<User>(cached!);
        }

        var user = await _db.Users.FindAsync(id);
        if (user is null) return null;

        var json = JsonSerializer.Serialize(user);
        await _redis.StringSetAsync($"user:{id}", json, TimeSpan.FromMinutes(5));
        return user;
    }

    public async Task UpdateUserAsync(User user)
    {
        _db.Users.Update(user);
        await _db.SaveChangesAsync();
        await _redis.KeyDeleteAsync($"user:{user.Id}");
    }
}

// Cache-aside in Node.js
const Redis = require('ioredis');
const redis = new Redis(process.env.REDIS_URL);

async function getUser(id) {
  const cached = await redis.get(`user:${id}`);
  if (cached) return JSON.parse(cached);

  const user = await db('users').where('id', id).first();
  if (!user) return null;

  await redis.setex(`user:${id}`, 300, JSON.stringify(user));
  return user;
}

async function updateUser(user) {
  await db('users').where('id', user.id).update(user);
  await redis.del(`user:${user.id}`);
}
